/**
 * The decorative layer — texture and hand-drawn strokes, made here rather than
 * generated by a model.
 *
 * ── What this is protecting ──
 * Every AI deck tool that has paper grain and drawn-looking rules gets them by
 * painting the whole slide with an image model. That costs a key, costs seconds
 * a page, and costs the only thing that really matters: the output is a picture
 * of a slide, so changing one word means repainting the page.
 *
 * Doing it with SVG buys all of it back — but only if three things hold, and
 * each of them fails silently:
 *
 *   1. ORDER. SVG reaches a slide through setSelectedDataAsync, which APPENDS.
 *      A background inserted after the shapes is not a background; it is a
 *      rectangle covering the content.
 *   2. NO DOUBLE GROUND. The flat ground band has to stand down when the
 *      ornament is carrying it, or the texture is painted over immediately.
 *   3. DETERMINISM. A wobble from Math.random means slide 4 looks different
 *      every time it is rebuilt — which nobody reads as 「手繪風」, they read it
 *      as a tool that cannot be trusted.
 */
import { ornamentSvg, handLine, handFrame, paper } from '../src/taskpane/hosts/svgart.js';

let pass = 0, fail = 0;
const ok = (name, cond, detail) => {
  cond ? pass++ : fail++;
  console.log(`${cond ? 'PASS' : 'FAIL'}  ${name}${cond ? '' : '  → ' + (detail || '')}`);
};

// ── The generator, on its own ────────────────────────────────────────────────

const TH = {
  strong: '#3E4A45', accent: '#A8705A', ground: '#F7F2E9',
  tint: '#F1EDE5', line: '#E2DAD0',
};

ok('沒有紋理也沒有手繪就不產生裝飾層',
  ornamentSvg({ theme: TH }) === null,
  '多插一張空白 SVG 就是多一次來回，而且多一個會蓋住東西的物件');

{
  const svg = ornamentSvg({ texture: 'paper', theme: TH, ground: TH.ground });
  ok('紙紋是一張完整的 SVG', /^<svg[^>]*viewBox="0 0 960 540"/.test(svg), svg.slice(0, 60));
  ok('底色鋪滿整頁', svg.includes(`fill="${TH.ground}"`));
  ok('紙紋用雜訊濾鏡', svg.includes('feTurbulence'));
  // 濾鏡失效的話會退回一塊平的色塊——也就是沒有紋理的版式本來的樣子。
  // 降級成預設，不是降級成空白。
  ok('濾鏡失效也還有底色', (svg.match(/<rect/g) || []).length >= 2);
}

{
  const a = handLine(38, 93, 146, 93, { color: '#000', seed: 7 });
  const b = handLine(38, 93, 146, 93, { color: '#000', seed: 7 });
  ok('同樣的種子畫出同樣的線', a === b,
    '每次重畫都長不一樣，沒有人會覺得那是手繪，只會覺得工具不可靠');
  ok('不同種子畫出不同的線', a !== handLine(38, 93, 146, 93, { color: '#000', seed: 8 }));
  // PowerPoint 的 SVG 支援對形狀很完整，對濾鏡很看運氣。線條的抖動做在座標上，
  // 不做在 feDisplacementMap 上，就是為了這個。
  ok('手繪線是純幾何，沒有用濾鏡',
    !a.includes('filter') && a.includes('<polyline'), a.slice(0, 80));
  ok('描兩次，像筆走過兩遍', (a.match(/<polyline/g) || []).length === 2);

  const pts = /points="([^"]+)"/.exec(a)[1].split(' ').map((s) => s.split(',').map(Number));
  // 中間可以晃，兩端要落在原本要去的地方——自己都沒畫到終點的線讀起來是壞掉。
  ok('起點準確', Math.abs(pts[0][0] - 38) < 0.01 && Math.abs(pts[0][1] - 93) < 0.01,
    JSON.stringify(pts[0]));
  ok('終點準確', Math.abs(pts[pts.length - 1][0] - 146) < 0.01, JSON.stringify(pts.at(-1)));
  ok('中間真的有晃', pts.some((p) => Math.abs(p[1] - 93) > 0.2),
    pts.map((p) => p[1]).join(' '));
}

ok('手繪框是四條線', (handFrame(26, 26, 908, 488, { color: '#000' })
  .match(/<polyline/g) || []).length === 8, '四條邊，每條描兩次');

{
  const svg = ornamentSvg({ strokes: 'hand', theme: TH, ground: '#FFF', title: true, topPad: 10 });
  ok('手繪版式有框', svg.includes('<polyline'));
  // 標題底線的位置跟其他版式的固定短線一樣——裝飾層換的是畫法，不是位置。
  ok('標題底線畫在骨架原本那條線的位置', /,10[0-9]/.test(svg) || svg.includes('103'),
    '固定短線在 y=89+4，加上 topPad 10 之後是 103');
  const noTitle = ornamentSvg({ strokes: 'hand', theme: TH, ground: '#FFF', title: false });
  ok('沒有標題就不畫那條底線',
    (noTitle.match(/<polyline/g) || []).length < (svg.match(/<polyline/g) || []).length,
    '一條不屬於任何標題的線就只是一個記號');
}

ok('點陣底是 pattern，不是幾百個圓',
  ornamentSvg({ texture: 'dots', theme: TH, ground: TH.ground }).includes('<pattern'));

// XML 一破，整張投影片的底就沒了，而且 Office 不會說為什麼。
for (const spec of [
  { texture: 'paper', theme: TH, ground: '#F7F2E9' },
  { texture: 'dots', theme: TH, ground: '#FFF' },
  { texture: 'wash', theme: TH, ground: '#FFF' },
  { strokes: 'hand', theme: TH, ground: '#FFF', title: true, footband: true },
]) {
  const svg = ornamentSvg(spec);
  const key = spec.texture || spec.strokes;
  ok(`${key}：標籤有開有關`,
    (svg.match(/</g) || []).length === (svg.match(/>/g) || []).length
      && svg.endsWith('</svg>'));
  ok(`${key}：沒有裸露的 & 或引號破洞`,
    !/&(?!amp;|lt;|gt;|quot;)/.test(svg) && (svg.match(/"/g) || []).length % 2 === 0);
}

{
  // 值是直接寫進屬性的，沒有轉義的話一個引號就能把 SVG 弄壞。
  const svg = paper('"><script>alert(1)</script>');
  ok('顏色值有轉義', !svg.includes('<script>'), svg.slice(0, 120));
}

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
